46	typedef struct {
47	    uint8_t dma_id;
48	    beken_semaphore_t dma_sema;
49	    dma_isr_t dma_finish_isr;
50	    bool dma_is_repeat_mode;
51	    bool lcd_qspi_is_init;
52	    uint32_t qspi_data;
53	    uint8_t dc_pin;
54	} lcd_spi_disp_t;
