56	static void lcd_spi0_dma_finish_isr(dma_id_t dma_id);
57	static void lcd_spi1_dma_finish_isr(dma_id_t dma_id);
58	
59	static lcd_spi_disp_t s_spi_disp[SOC_QSPI_UNIT_NUM] = {
60	    {
61	        .dma_finish_isr = lcd_spi0_dma_finish_isr,
62	        .dma_is_repeat_mode = false,
63	        .lcd_qspi_is_init = false,
64	        .qspi_data = LCD_QSPI0_DATA_ADDR,
65	    },
66	    {
67	        .dma_finish_isr = lcd_spi1_dma_finish_isr,
68	        .dma_is_repeat_mode = false,
69	        .lcd_qspi_is_init = false,
70	        .qspi_data = LCD_QSPI1_DATA_ADDR,
71	    },
72	};
73	
74	static void lcd_spi_dma_finish_handler(qspi_id_t qspi_id, dma_id_t dma_id, bool dma_is_repeat_mode)
75	{
76	    bk_err_t ret = BK_OK;
77	    uint32_t value = 0;
78	
79	    if (dma_is_repeat_mode) {
80	        value = bk_dma_get_repeat_wr_pause(dma_id);
81	        if (value) {
82	            bk_dma_stop(dma_id);
83	
84	            ret = rtos_set_semaphore(&s_spi_disp[qspi_id].dma_sema);
85	            if (ret != BK_OK) {
86	                LCD_SPI_LOGE("lcd qspi dma semaphore set failed\r\n");
87	                return;
88	            }
89	        }
90	    } else {
91	        ret = rtos_set_semaphore(&s_spi_disp[qspi_id].dma_sema);
92	        if (ret != BK_OK) {
93	            LCD_SPI_LOGE("lcd qspi dma semaphore set failed\r\n");
94	            return;
95	        }
96	    }
97	}
98	
99	static void lcd_spi0_dma_finish_isr(dma_id_t dma_id)
100	{
101	    lcd_spi_dma_finish_handler(QSPI_ID_0, dma_id, s_spi_disp[0].dma_is_repeat_mode);
102	}
103	
104	static void lcd_spi1_dma_finish_isr(dma_id_t dma_id)
105	{
106	    lcd_spi_dma_finish_handler(QSPI_ID_1, dma_id, s_spi_disp[1].dma_is_repeat_mode);
107	}
