109	static void lcd_spi_device_gpio_init(uint8_t reset_pin, uint8_t dc_pin)
110	{
111	    BK_LOG_ON_ERR(bk_gpio_driver_init());
112	
113	    gpio_config_t config;
114	    config.io_mode = GPIO_OUTPUT_ENABLE;
115	    config.pull_mode = GPIO_PULL_DISABLE;
116	    config.func_mode = GPIO_SECOND_FUNC_DISABLE;
117	
118	    BK_LOG_ON_ERR(gpio_dev_unmap(reset_pin));
119	    BK_LOG_ON_ERR(gpio_dev_unmap(dc_pin));
120	    bk_gpio_set_config(reset_pin, &config);
121	    bk_gpio_set_config(dc_pin, &config);
122	
123	    BK_LOG_ON_ERR(bk_gpio_set_output_high(reset_pin));
124	    BK_LOG_ON_ERR(bk_gpio_set_output_high(dc_pin));
125	
126	    BK_LOG_ON_ERR(bk_gpio_set_output_low(reset_pin));
127	    rtos_delay_milliseconds(100);
