203	static bk_err_t lcd_spi_get_dma_repeat_once_len(uint32_t data_len)
204	{
205	    uint32_t len = 0;
206	    uint32_t value = 0;
207	    uint8_t i = 0;
208	
209	    for (i = 2; i < 25; i++) {
210	        len = data_len / i;
211	        if (len <= 0x10000) {
212	            value = data_len % i;
213	            if (!value) {
214	                return len;
215	            }
216	        }
217	    }
218	    LCD_SPI_LOGE("%s Error dma length, please check the data_len parameter\r\n", __func__);
219	
220	    return len;
221	}
