223	static void lcd_spi_dma_single_mode_config(qspi_id_t qspi_id, dma_id_t dma_id, uint8_t *data, uint32_t data_len)
224	{
225	    bk_err_t ret = BK_OK;
226	    dma_config_t dma_config = {0};
227	
228	    dma_config.mode = DMA_WORK_MODE_SINGLE;
229	    dma_config.chan_prio = 0;
230	
231	    dma_config.src.dev = DMA_DEV_DTCM;
232	    dma_config.src.width = DMA_DATA_WIDTH_32BITS;
233	    dma_config.src.addr_inc_en = DMA_ADDR_INC_ENABLE;
234	    dma_config.src.start_addr = (uint32_t)data;
235	    dma_config.src.end_addr = (uint32_t)(data + data_len);
236	
237	    dma_config.dst.dev = DMA_DEV_DTCM;
238	    dma_config.dst.width = DMA_DATA_WIDTH_32BITS;
239	    dma_config.dst.addr_inc_en = DMA_ADDR_INC_ENABLE;
240	
241	    dma_config.dst.start_addr = s_spi_disp[qspi_id].qspi_data;
242	    dma_config.dst.end_addr = s_spi_disp[qspi_id].qspi_data + data_len;
