244	    ret = bk_dma_init(dma_id, &dma_config);
245	    if (ret != BK_OK) {
246	        LCD_SPI_LOGE("bk_dma_init failed!\r\n");
247	        return;
248	    }
249	
250	    bk_dma_set_transfer_len(dma_id, data_len);
251	    bk_dma_register_isr(s_spi_disp[qspi_id].dma_id, NULL, s_spi_disp[qspi_id].dma_finish_isr);
252	    bk_dma_enable_finish_interrupt(s_spi_disp[qspi_id].dma_id);
