256	{
257	    uint32_t dma_repeat_once_len = 0;
258	
259	    bk_dma_stateless_judgment_configuration((void *)s_spi_disp[qspi_id].qspi_data, (void *)data, data_len, dma_id, s_spi_disp[qspi_id].dma_finish_isr);
