390	static void lcd_spi_send_data_with_qspi_cmd_c(qspi_id_t qspi_id, uint8_t *data, uint32_t data_len)
391	{
392	    uint32_t value = 0;
393	
394	    qspi_hal_set_cmd_c_l(&s_lcd_spi[qspi_id].hal, 0);
395	    qspi_hal_set_cmd_c_h(&s_lcd_spi[qspi_id].hal, 0);
396	    qspi_hal_set_cmd_c_cfg1(&s_lcd_spi[qspi_id].hal, 0);
397	    qspi_hal_set_cmd_c_cfg2(&s_lcd_spi[qspi_id].hal, 0);
398	
399	    for (uint8_t i = 0; i < data_len; i++) {
400	        value |= (data[i] << (i * 8));
401	    }
402	
403	    qspi_hal_set_cmd_c_h(&s_lcd_spi[qspi_id].hal, value);
404	    qspi_hal_set_cmd_c_cfg1(&s_lcd_spi[qspi_id].hal, 0x3 << (data_len * 2));
405	    qspi_hal_cmd_c_start(&s_lcd_spi[qspi_id].hal);
406	    qspi_hal_wait_cmd_done(&s_lcd_spi[qspi_id].hal);
407	}
408	
409	static void lcd_spi_send_data_with_qspi_indirect_mode(qspi_id_t qspi_id, uint8_t *data, uint32_t data_len)
410	{
411	    uint32_t value = 0;
412	    uint32_t send_len = 0;
413	    uint32_t remain_len = data_len;
414	    uint8_t *data_tmp = data;
415	
416	    qspi_hal_set_cmd_c_l(&s_lcd_spi[qspi_id].hal, 0);
417	    qspi_hal_set_cmd_c_h(&s_lcd_spi[qspi_id].hal, 0);
418	    qspi_hal_set_cmd_c_cfg1(&s_lcd_spi[qspi_id].hal, 0);
419	    qspi_hal_set_cmd_c_cfg2(&s_lcd_spi[qspi_id].hal, 0);
420	
421	    while (remain_len > 0) {
422	        if (remain_len <= 4) {
423	            lcd_spi_send_data_with_qspi_cmd_c(qspi_id, data_tmp, remain_len);
424	            break;
425	        }
426	
427	        value = (data_tmp[3] << 24) | (data_tmp[2] << 16) | (data_tmp[1] << 8) | data_tmp[0];
428	        remain_len -= 4;
429	        send_len = remain_len < 0x100 ? remain_len : 0x100;
430	        qspi_hal_set_cmd_c_h(&s_lcd_spi[qspi_id].hal, value);
431	        qspi_hal_set_cmd_c_cfg1(&s_lcd_spi[qspi_id].hal, 0x300);
432	        qspi_hal_set_cmd_c_cfg2(&s_lcd_spi[qspi_id].hal, send_len << 2);
433	        data_tmp += 4;
434	        bk_qspi_write(qspi_id, data_tmp, send_len);
435	        qspi_hal_cmd_c_start(&s_lcd_spi[qspi_id].hal);
436	        qspi_hal_wait_cmd_done(&s_lcd_spi[qspi_id].hal);
437	        remain_len -= send_len;
438	        data_tmp += send_len;
439	    }
440	}
