536	static void lcd_spi_disp_area_config(uint8_t id, lcd_display_area_t *area)
537	{
538	    uint8_t column_value[4] = {0};
539	    uint8_t row_value[4] = {0};
540	
541	    column_value[0] = (area->x_start >> 8) & 0xFF;
542	    column_value[1] = area->x_start & 0xFF;
543	    column_value[2] = (area->x_end >> 8) & 0xFF;
544	    column_value[3] = area->x_end & 0xFF;
545	    row_value[0] = (area->y_start >> 8) & 0xFF;
546	    row_value[1] = area->y_start & 0xFF;
547	    row_value[2] = (area->y_end >> 8) & 0xFF;
548	    row_value[3] = area->y_end & 0xFF;
549	
550	    bk_lcd_spi_send_cmd(id, LCD_SPI_DEVICE_CASET);
551	    bk_lcd_spi_send_data(id, column_value, 4);
552	    bk_lcd_spi_send_cmd(id, LCD_SPI_DEVICE_RASET);
553	    bk_lcd_spi_send_data(id, row_value, 4);
554	}
