556	void bk_lcd_spi_init(uint8_t id, const lcd_device_t *device, uint8_t reset_pin, uint8_t dc_pin)
557	{
558	    if (device == NULL) {
559	        LCD_SPI_LOGE("lcd spi device not found\r\n");
560	        return;
561	    }
562	
563	    if (s_spi_disp[id].lcd_qspi_is_init) {
564	        LCD_SPI_LOGE("lcd qspi init already complete\r\n");
565	        return;
566	    }
567	
568	#if (CONFIG_LCD_SPI_REFRESH_WITH_QSPI)
569	#if (CONFIG_LCD_SPI_REFRESH_WITH_QSPI_MAPPING_MODE)
570	    lcd_spi_dma_init(id);
571	#endif
572	
573	    lcd_spi_driver_init_with_qspi(id, device->spi->clk);
574	#else // CONFIG_LCD_SPI_REFRESH_WITH_QSPI
575	    lcd_spi_driver_init(id);
576	#endif
577	
578	    lcd_spi_device_gpio_init(reset_pin, dc_pin);
579	    s_spi_disp[id].dc_pin = dc_pin;
580	
581	    if (device->spi->init_cmd != NULL) {
582	        const lcd_qspi_init_cmd_t *init = device->spi->init_cmd;
583	        for (uint32_t i = 0; i < device->spi->device_init_cmd_len; i++) {
584	            if (init->data_len == 0xFF) {
585	                rtos_delay_milliseconds(init->data[0]);
586	            } else {
587	                bk_lcd_spi_send_cmd(id, init->cmd);
588	                if (init->data_len != 0) {
589	                    bk_lcd_spi_send_data(id, (uint8_t *)init->data, init->data_len);
590	                }
591	            }
592	            init++;
593	        }
594	    } else {
595	        LCD_SPI_LOGE("lcd spi device init cmd is null\r\n");
596	        return;
597	    }
598	
599	    lcd_display_area_t disp_area = {0};
600	    disp_area.x_start = 0;
601	    disp_area.y_start = 0;
602	    disp_area.x_end = device->width - 1;
603	    disp_area.y_end = device->height - 1;
