/****************************************************************************
 * Bit-bang SPI driver for the GC9D01 160x160 RGB565 LCD on BK7258 DevKit.
 *
 * Pin mapping (from schematic, confirmed against ARMINO gpio_map.h):
 *   SCLK = GPIO_2  (QSPI1_CLK, func6 — unused for bit-bang)
 *   CS   = GPIO_3  (QSPI1_CSN, func6 — unused for bit-bang)
 *   MOSI = GPIO_4  (QSPI1_IO0, func6 — unused for bit-bang)
 *   DC   = GPIO_5  (QSPI1_IO1, func6 — unused for bit-bang)
 *   RST  = GPIO_45 (LCD_B5 in RGB mode — unused here)
 *   BL   = GPIO_25 (LCD_G6 in RGB mode — unused here)
 *
 * The GC9D01 uses a separate DC pin (not 9-bit SPI).  DC=LOW for command,
 * DC=HIGH for data.  SPI mode 0, MSB first.
 *
 * This is a minimal bring-up driver: bit-bang only, no DMA, no QSPI hw.
 * Purpose: prove the bus / init sequence / backlight work before writing
 * a proper QSPI1 hardware driver.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <string.h>
#include <debug.h>

#include <nuttx/arch.h>

#include "arm_internal.h"
#include "hardware/bk7258_memorymap.h"
#include "hardware/bk7258_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* LCD pin assignments (GPIO numbers) */

#define LCD_PIN_SCLK   2
#define LCD_PIN_CS     3
#define LCD_PIN_MOSI   4
#define LCD_PIN_DC     5
#define LCD_PIN_RST    45
#define LCD_PIN_BL     25

/* Display geometry */

#define LCD_WIDTH      160
#define LCD_HEIGHT     160
#define LCD_BPP        16  /* RGB565 */
#define LCD_FRAMEBUFFER_SIZE (LCD_WIDTH * LCD_HEIGHT * (LCD_BPP / 8))

/* SPI bit-bang delay: ~60 ns per toggle at 120 MHz Cortex-M33.
 * A few NOPs give a comfortable margin below the GC9D01 max SCLK.
 */

#define spi_delay()    do { __asm__ volatile("nop; nop; nop; nop;"); } while (0)

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Full-screen framebuffer in DTCM (fast, 51 KB).
 * Placed in .bss so it is zero-filled at boot.
 */

static uint8_t g_framebuffer[LCD_FRAMEBUFFER_SIZE]
__attribute__((aligned(4)));

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: gpio_set_output
 *
 * Description:
 *   Configure a pin as GPIO output, disable secondary function.
 *
 ****************************************************************************/

static void gpio_set_output(int pin)
{
  uint32_t cfg;

  /* Disable secondary function (bit6=0), enable output (bit3=1),
   * set output value to 0 (bit1=0 initially).
   */

  cfg = getreg32(BK7258_GPIO_CFG(pin));
  cfg &= ~GPIO_CFG_SECOND_FUNC;
  cfg |= GPIO_CFG_OUTPUT_EN;
  cfg &= ~GPIO_CFG_INPUT_EN;
  putreg32(cfg, BK7258_GPIO_CFG(pin));
}

/****************************************************************************
 * Name: gpio_write
 *
 * Description:
 *   Set a GPIO output pin high (val=1) or low (val=0).
 *
 ****************************************************************************/

static void gpio_write(int pin, int val)
{
  uint32_t cfg;

  cfg = getreg32(BK7258_GPIO_CFG(pin));
  if (val)
    {
      cfg |= GPIO_CFG_OUTPUT;
    }
  else
    {
      cfg &= ~GPIO_CFG_OUTPUT;
    }

  putreg32(cfg, BK7258_GPIO_CFG(pin));
}

/****************************************************************************
 * Name: spi_write_byte
 *
 * Description:
 *   Bit-bang one byte over SPI (mode 0, MSB first).
 *
 ****************************************************************************/

static void spi_write_byte(uint8_t byte)
{
  int bit;

  for (bit = 7; bit >= 0; bit--)
    {
      gpio_write(LCD_PIN_MOSI, (byte >> bit) & 1);
      spi_delay();
      gpio_write(LCD_PIN_SCLK, 1);
      spi_delay();
      gpio_write(LCD_PIN_SCLK, 0);
    }
}

/****************************************************************************
 * Name: lcd_cs_low / lcd_cs_high
 *
 * Description:
 *   Assert / deassert chip select (active low).
 *
 ****************************************************************************/

static inline void lcd_cs_low(void)
{
  gpio_write(LCD_PIN_CS, 0);
}

static inline void lcd_cs_high(void)
{
  gpio_write(LCD_PIN_CS, 1);
}

/****************************************************************************
 * Name: lcd_send_cmd
 *
 * Description:
 *   Send a single command byte (DC=LOW).
 *
 ****************************************************************************/

static void lcd_send_cmd(uint8_t cmd)
{
  gpio_write(LCD_PIN_DC, 0);
  lcd_cs_low();
  spi_write_byte(cmd);
  lcd_cs_high();
}

/****************************************************************************
 * Name: lcd_send_data
 *
 * Description:
 *   Send data bytes (DC=HIGH).
 *
 ****************************************************************************/

static void lcd_send_data(const uint8_t *data, int len)
{
  int i;

  gpio_write(LCD_PIN_DC, 1);
  lcd_cs_low();
  for (i = 0; i < len; i++)
    {
      spi_write_byte(data[i]);
    }

  lcd_cs_high();
}

/****************************************************************************
 * Name: lcd_send_cmd_data
 *
 * Description:
 *   Send a command followed by its data bytes.
 *
 ****************************************************************************/

static void lcd_send_cmd_data(uint8_t cmd, const uint8_t *data, int len)
{
  lcd_send_cmd(cmd);
  if (len > 0)
    {
      lcd_send_data(data, len);
    }
}

/****************************************************************************
 * Name: lcd_delay_ms
 *
 * Description:
 *   Blocking millisecond delay (uses NuttX up_mdelay).
 *
 ****************************************************************************/

#define lcd_delay_ms(ms) up_mdelay(ms)

/****************************************************************************
 * Name: lcd_init_sequence
 *
 * Description:
 *   GC9D01 initialization sequence from ARMINO lcd_spi_gc9d01.c.
 *
 ****************************************************************************/

static void lcd_init_sequence(void)
{
  /* Enter extended command mode */

  lcd_send_cmd(0xfe);
  lcd_send_cmd(0xef);

  /* Enable commands 0x80-0x8f (all 0xff) */

  lcd_send_cmd_data(0x80, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x81, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x82, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x83, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x84, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x85, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x86, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x87, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x88, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x89, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x8a, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x8b, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x8c, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x8d, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x8e, (const uint8_t *)"\xff", 1);
  lcd_send_cmd_data(0x8f, (const uint8_t *)"\xff", 1);

  /* Pixel format: RGB565 (16 bpp) */

  lcd_send_cmd_data(0x3a, (const uint8_t *)"\x05", 1);
  lcd_send_cmd_data(0xec, (const uint8_t *)"\x01", 1);

  lcd_send_cmd_data(0x74,
    (const uint8_t *)"\x02\x0e\x00\x00\x00\x00\x00", 7);
  lcd_send_cmd_data(0x98, (const uint8_t *)"\x3e\x99\x3e", 3);
  lcd_send_cmd_data(0xb5, (const uint8_t *)"\x0d\x0d", 2);

  lcd_send_cmd_data(0x60,
    (const uint8_t *)"\x38\x0f\x79\x67", 4);
  lcd_send_cmd_data(0x61,
    (const uint8_t *)"\x38\x11\x79\x67", 4);
  lcd_send_cmd_data(0x64,
    (const uint8_t *)"\x38\x17\x71\x5f\x79\x67", 6);
  lcd_send_cmd_data(0x65,
    (const uint8_t *)"\x38\x13\x71\x5b\x79\x67", 6);
  lcd_send_cmd_data(0x6a, (const uint8_t *)"\x00\x00", 2);
  lcd_send_cmd_data(0x6c,
    (const uint8_t *)"\x22\x02\x22\x02\x22\x22\x50", 7);
  lcd_send_cmd_data(0x6e,
    (const uint8_t *)"\x03\x03\x01\x01\x00\x00"
                     "\x0f\x0f\x0d\x0d\x0b\x0b"
                     "\x09\x09\x00\x00\x00\x00"
                     "\x0a\x0a\x0c\x0c\x0e\x0e"
                     "\x10\x10\x00\x00\x02\x02"
                     "\x04\x04", 32);

  lcd_send_cmd_data(0xbf, (const uint8_t *)"\x01", 1);
  lcd_send_cmd_data(0xf9, (const uint8_t *)"\x40", 1);
  lcd_send_cmd_data(0x9b, (const uint8_t *)"\x3b", 1);
  lcd_send_cmd_data(0x93, (const uint8_t *)"\x33\x7f\x00", 3);
  lcd_send_cmd_data(0x7e, (const uint8_t *)"\x30", 1);
  lcd_send_cmd_data(0x70,
    (const uint8_t *)"\x0d\x02\x08\x0d\x02\x08", 6);
  lcd_send_cmd_data(0x71,
    (const uint8_t *)"\x0d\x02\x08", 3);
  lcd_send_cmd_data(0x91, (const uint8_t *)"\x0e\x09", 2);
  lcd_send_cmd_data(0xc3, (const uint8_t *)"\x18", 1);
  lcd_send_cmd_data(0xc4, (const uint8_t *)"\x18", 1);
  lcd_send_cmd_data(0xc9, (const uint8_t *)"\x3c", 1);

  /* Gamma curves */

  lcd_send_cmd_data(0xf0,
    (const uint8_t *)"\x13\x15\x04\x05\x01\x38", 6);
  lcd_send_cmd_data(0xf2,
    (const uint8_t *)"\x13\x15\x04\x05\x01\x34", 6);
  lcd_send_cmd_data(0xf1,
    (const uint8_t *)"\x4b\xb8\x7b\x34\x35\xef", 6);
  lcd_send_cmd_data(0xf3,
    (const uint8_t *)"\x47\xb4\x72\x34\x35\xda", 6);

  /* MADCTL: normal orientation */

  lcd_send_cmd_data(0x36, (const uint8_t *)"\x00", 1);

  /* Tearing effect off, sleep out, display on */

  lcd_send_cmd(0x34);
  lcd_send_cmd(0x11);
  lcd_delay_ms(120);
  lcd_send_cmd(0x29);
}

/****************************************************************************
 * Name: lcd_set_window
 *
 * Description:
 *   Set the drawing window (column and row address).
 *
 ****************************************************************************/

static void lcd_set_window(uint16_t x0, uint16_t y0,
                           uint16_t x1, uint16_t y1)
{
  uint8_t ca[4];
  uint8_t ra[4];

  ca[0] = (x0 >> 8) & 0xff;
  ca[1] = x0 & 0xff;
  ca[2] = (x1 >> 8) & 0xff;
  ca[3] = x1 & 0xff;

  ra[0] = (y0 >> 8) & 0xff;
  ra[1] = y0 & 0xff;
  ra[2] = (y1 >> 8) & 0xff;
  ra[3] = y1 & 0xff;

  lcd_send_cmd_data(0x2a, ca, 4);  /* CASET */
  lcd_send_cmd_data(0x2b, ra, 4);  /* RASET */
}

/****************************************************************************
 * Name: lcd_fill_color
 *
 * Description:
 *   Fill the entire framebuffer with a RGB565 color and push to LCD.
 *
 ****************************************************************************/

static void lcd_fill_color(uint16_t color)
{
  uint8_t hi = (color >> 8) & 0xff;
  uint8_t lo = color & 0xff;
  int i;

  /* Fill framebuffer */

  for (i = 0; i < LCD_FRAMEBUFFER_SIZE; i += 2)
    {
      g_framebuffer[i]     = hi;
      g_framebuffer[i + 1] = lo;
    }

  /* Set full window and stream pixels */

  lcd_set_window(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1);
  lcd_send_cmd(0x2c);  /* RAMWR */

  gpio_write(LCD_PIN_DC, 1);
  lcd_cs_low();
  for (i = 0; i < LCD_FRAMEBUFFER_SIZE; i++)
    {
      spi_write_byte(g_framebuffer[i]);
    }

  lcd_cs_high();
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_gc9d01_initialize
 *
 * Description:
 *   Initialize the GC9D01 LCD via bit-bang SPI and fill with red.
 *   Called from bk7258_bringup().
 *
 ****************************************************************************/

int bk7258_gc9d01_initialize(void)
{
  lcdinfo("bk7258_gc9d01_initialize: start\n");

  /* Configure all LCD pins as GPIO output */

  gpio_set_output(LCD_PIN_SCLK);
  gpio_set_output(LCD_PIN_CS);
  gpio_set_output(LCD_PIN_MOSI);
  gpio_set_output(LCD_PIN_DC);
  gpio_set_output(LCD_PIN_RST);
  gpio_set_output(LCD_PIN_BL);

  /* Default pin states: CS high, DC high, SCLK low, MOSI low */

  gpio_write(LCD_PIN_CS, 1);
  gpio_write(LCD_PIN_DC, 1);
  gpio_write(LCD_PIN_SCLK, 0);
  gpio_write(LCD_PIN_MOSI, 0);

  /* Backlight on */

  gpio_write(LCD_PIN_BL, 1);

  /* Hardware reset: LOW >= 10 ms, then HIGH >= 120 ms */

  gpio_write(LCD_PIN_RST, 0);
  lcd_delay_ms(10);
  gpio_write(LCD_PIN_RST, 1);
  lcd_delay_ms(120);

  /* Send GC9D01 initialization sequence */

  lcd_init_sequence();

  lcdinfo("bk7258_gc9d01_initialize: init sequence done, filling red\n");

  /* Fill screen with red (RGB565 = 0xf800) as a visual smoke test */

  lcd_fill_color(0xf800);

  lcdinfo("bk7258_gc9d01_initialize: done\n");
  return OK;
}

