358	static void lcd_set_window(uint16_t x0, uint16_t y0,
359	                           uint16_t x1, uint16_t y1)
360	{
361	  uint8_t ca[4];
362	  uint8_t ra[4];
363	
364	  ca[0] = (x0 >> 8) & 0xff;
365	  ca[1] = x0 & 0xff;
366	  ca[2] = (x1 >> 8) & 0xff;
367	  ca[3] = x1 & 0xff;
368	
369	  ra[0] = (y0 >> 8) & 0xff;
370	  ra[1] = y0 & 0xff;
371	  ra[2] = (y1 >> 8) & 0xff;
372	  ra[3] = y1 & 0xff;
373	
374	  lcd_send_cmd_data(0x2a, ca, 4);  /* CASET */
375	  lcd_send_cmd_data(0x2b, ra, 4);  /* RASET */
