378	/****************************************************************************
379	 * Name: lcd_fill_color
380	 *
381	 * Description:
382	 *   Fill the entire framebuffer with a RGB565 color and push to LCD.
383	 *
384	 ****************************************************************************/
385	
386	static void lcd_fill_color(uint16_t color)
387	{
388	  uint8_t hi = (color >> 8) & 0xff;
389	  uint8_t lo = color & 0xff;
390	  int i;
391	
392	  /* Fill framebuffer */
393	
394	  for (i = 0; i < LCD_FRAMEBUFFER_SIZE; i += 2)
395	    {
396	      g_framebuffer[i]     = hi;
397	      g_framebuffer[i + 1] = lo;
398	    }
399	
400	  /* Set full window and stream pixels */
401	
402	  lcd_set_window(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1);
403	  lcd_send_cmd(0x2c);  /* RAMWR */
404	
405	  gpio_write(LCD_PIN_DC, 1);
406	  lcd_cs_low();
407	  for (i = 0; i < LCD_FRAMEBUFFER_SIZE; i++)
408	    {
409	      spi_write_byte(g_framebuffer[i]);
410	    }
411	
412	  lcd_cs_high();
413	}
