432	  /* Configure all LCD pins as GPIO output */
433	
434	  gpio_set_output(LCD_PIN_SCLK);
435	  gpio_set_output(LCD_PIN_CS);
436	  gpio_set_output(LCD_PIN_MOSI);
437	  gpio_set_output(LCD_PIN_DC);
438	  gpio_set_output(LCD_PIN_RST);
439	  gpio_set_output(LCD_PIN_BL);
440	
441	  /* Default pin states: CS high, DC high, SCLK low, MOSI low */
442	
443	  gpio_write(LCD_PIN_CS, 1);
444	  gpio_write(LCD_PIN_DC, 1);
445	  gpio_write(LCD_PIN_SCLK, 0);
446	  gpio_write(LCD_PIN_MOSI, 0);
447	
448	  /* Backlight on */
449	
450	  gpio_write(LCD_PIN_BL, 1);
451	
452	  /* Hardware reset: LOW >= 10 ms, then HIGH >= 120 ms */
453	
454	  gpio_write(LCD_PIN_RST, 0);
455	  lcd_delay_ms(10);
456	  gpio_write(LCD_PIN_RST, 1);
457	  lcd_delay_ms(120);
458	
459	  /* Send GC9D01 initialization sequence */
460	
461	  lcd_init_sequence();
462	
463	  lcdinfo("bk7258_gc9d01_initialize: init sequence done, filling red\n");
464	
465	  /* Fill screen with red (RGB565 = 0xf800) as a visual smoke test */
466	
467	  lcd_fill_color(0xf800);
468	
469	  lcdinfo("bk7258_gc9d01_initialize: done\n");
470	  return OK;
471	}
