 * Description:
 *   Staged LCD bring-up: A=backlight, B=init, C=40x40 red square.
 *
 ****************************************************************************/

static int lcdtest_stages(void)
{
  /* --- Stage A: backlight --- */

  syslog(LOG_INFO,
         "[lcdtest] Stage A: backlight ON (P25 high)\n");

  gpio_set_output(LCD_PIN_BL);
  gpio_write(LCD_PIN_BL, 1);
