/****************************************************************************
 * Name: lcdtest_pwr
 *
 * Description:
 *   Full power-on sequence: drive all possible power/enable GPIOs high,
 *   wait for supply stabilisation, then init the LCD and draw a test
 *   pattern.  Use when the LCD power enable pin is unknown or when a
 *   reliable cold-boot bring-up is needed.
 *
 ****************************************************************************/

static int lcdtest_pwr(void)
{
  int pin;

  /* Step 1: drive GPIO 0-52 high (cumulative, skip reserved pins).
   * Skipped pins:
   *   2,3,4,5,25,29  — LCD SPI/ctrl signals (used later for init)
   *   10,11          — UART0 console (keep serial alive)
   *   7,8            — vibration motor (avoid noise)
   *   38,39          — red/green indicator LEDs
   */

  syslog(LOG_INFO,
         "[pwr] step1: GPIO 0-52 high (skip reserved) ...\n");

  for (pin = 0; pin <= 52; pin++)
    {
      /* LCD signals */

      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
          pin == 25 || pin == 29)
        {
          continue;
        }

      /* UART0 console */

      if (pin == 10 || pin == 11)
        {
          continue;
        }

      /* Vibration motor */

      if (pin == 7 || pin == 8)
        {
          continue;
        }

      /* Indicator LEDs */

      if (pin == 38 || pin == 39)
        {
          continue;
        }

      gpio_set_output(pin);
      gpio_write(pin, 1);
    }

  /* Step 2: wait for power rails to settle */

  syslog(LOG_INFO, "[pwr] step2: wait 50 ms ...\n");
  up_mdelay(50);

  /* Step 3: backlight on */

  syslog(LOG_INFO, "[pwr] step3: backlight P25 high\n");
  gpio_set_output(LCD_PIN_BL);
  gpio_write(LCD_PIN_BL, 1);

  /* Step 4: hardware reset */

  syslog(LOG_INFO,
         "[pwr] step4: RST(P29) low 15 ms then high\n");
  gpio_set_output(LCD_PIN_RST);
  gpio_write(LCD_PIN_RST, 0);
  up_mdelay(15);
  gpio_write(LCD_PIN_RST, 1);
  up_mdelay(120);

  /* Step 5: GC9D01 init sequence */

  syslog(LOG_INFO, "[pwr] step5: GC9D01 init sequence\n");
  lcd_init_sequence();

  /* Step 6: clear screen to black */

  syslog(LOG_INFO, "[pwr] step6: fill screen black\n");
  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);

  /* Step 7: draw 40x40 red square at (60,60) */

  syslog(LOG_INFO,
         "[pwr] step7: fill 40x40 red at (60,60)\n");
  lcd_fill_rect(60, 60,
                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
                0xf800);

  syslog(LOG_INFO, "[pwr] done - screen should show red on black\n");
  return OK;
}

