  if (argc > 1 && strcmp(argv[1], "pwr") == 0)
    {
      int lo = 0;
      int hi = 52;

      if (argc > 2)
        {
          lo = atoi(argv[2]);
        }

      if (argc > 3)
        {
          hi = atoi(argv[3]);
        }

      if (lo < 0)
        {
          lo = 0;
        }

      if (hi > 52)
        {
          hi = 52;
        }

      if (lo > hi)
        {
          syslog(LOG_ERR,
                 "[pwr] error: lo(%d) > hi(%d)\n", lo, hi);
          return -EINVAL;
        }

      return lcdtest_pwr(lo, hi);
    }

  return lcdtest_stages();
}

