279	  uint8_t hi = (color >> 8) & 0xff;
280	  uint8_t lo = color & 0xff;
281	  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);
282	  int i;
283	
284	  /* CASET */
285	
286	  ca[0] = (x0 >> 8) & 0xff;
287	  ca[1] = x0 & 0xff;
288	  ca[2] = (x1 >> 8) & 0xff;
289	  ca[3] = x1 & 0xff;
290	  lcd_send_cmd_data(0x2a, ca, 4);
291	
292	  /* RASET */
293	
294	  ra[0] = (y0 >> 8) & 0xff;
295	  ra[1] = y0 & 0xff;
296	  ra[2] = (y1 >> 8) & 0xff;
297	  ra[3] = y1 & 0xff;
298	  lcd_send_cmd_data(0x2b, ra, 4);
299	
300	  /* RAMWR + pixel data */
301	
302	  lcd_send_cmd(0x2c);
303	  gpio_write(LCD_PIN_DC, 1);
304	  gpio_write(LCD_PIN_CS, 0);
305	  for (i = 0; i < npix; i++)
306	    {
307	      spi_write_byte(hi);
308	      spi_write_byte(lo);
309	    }
310	
311	  gpio_write(LCD_PIN_CS, 1);
312	}
