318	/****************************************************************************
319	 * Name: lcdtest_stages
320	 *
321	 * Description:
322	 *   Staged LCD bring-up: A=backlight, B=init, C=40x40 red square.
323	 *
324	 ****************************************************************************/
325	
326	static int lcdtest_stages(void)
327	{
328	  /* --- Stage A: backlight --- */
329	
330	  syslog(LOG_INFO,
331	         "[lcdtest] Stage A: backlight ON (P25 high)\n");
332	
333	  gpio_set_output(LCD_PIN_BL);
334	  gpio_write(LCD_PIN_BL, 1);
335	  up_mdelay(1000);
336	
337	  syslog(LOG_INFO,
338	         "[lcdtest] Stage A done - screen should be lit white\n");
339	
340	  /* --- Stage B: reset + init --- */
341	
342	  syslog(LOG_INFO,
343	         "[lcdtest] Stage B: RST(P29) reset + GC9D01 init\n");
344	
345	  gpio_set_output(LCD_PIN_SCLK);
346	  gpio_set_output(LCD_PIN_CS);
347	  gpio_set_output(LCD_PIN_MOSI);
348	  gpio_set_output(LCD_PIN_DC);
349	  gpio_set_output(LCD_PIN_RST);
350	
351	  gpio_write(LCD_PIN_CS, 1);
352	  gpio_write(LCD_PIN_DC, 1);
353	  gpio_write(LCD_PIN_SCLK, 0);
354	  gpio_write(LCD_PIN_MOSI, 0);
355	
356	  gpio_write(LCD_PIN_RST, 0);
357	  up_mdelay(10);
358	  gpio_write(LCD_PIN_RST, 1);
359	  up_mdelay(120);
360	
361	  lcd_init_sequence();
362	
363	  syslog(LOG_INFO,
364	         "[lcdtest] Stage B done - panel initialized\n");
365	
366	  /* --- Stage C: 40x40 red square --- */
367	
368	  syslog(LOG_INFO,
369	         "[lcdtest] Stage C: fill 40x40 red at (60,60)\n");
370	
371	  lcd_fill_rect(60, 60,
372	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
373	                0xf800);
374	
375	  syslog(LOG_INFO,
376	         "[lcdtest] Stage C done - look for red square\n");
377	
378	  return OK;
379	}
