381	/****************************************************************************
382	 * Name: lcdtest_scan
383	 *
384	 * Description:
385	 *   Scan GPIO 0-47 for the LCD power enable pin.
386	 *   Strategy: cumulative — pull each pin high and leave it high, so that
387	 *   if multiple pins need to be high simultaneously the condition is met.
388	 *   P25 (backlight) is held high throughout.  UART console pins (10, 11)
389	 *   and LCD signal pins (2-5, 29) are skipped to keep the console and
390	 *   SPI bus alive.
391	 *
392	 ****************************************************************************/
393	
394	static int lcdtest_scan(void)
395	{
396	  int pin;
397	
398	  /* Backlight on first */
399	
400	  gpio_set_output(LCD_PIN_BL);
401	  gpio_write(LCD_PIN_BL, 1);
402	
403	  syslog(LOG_INFO,
404	         "[scan] backlight P25 high, scanning GPIO 0-47 ...\n");
405	
406	  for (pin = 0; pin <= 47; pin++)
407	    {
408	      /* Skip UART0 console: RX=10, TX=11 */
409	
410	      if (pin == 10 || pin == 11)
411	        {
412	          syslog(LOG_INFO,
413	                 "[scan] pin=%d skipped (UART0 console)\n", pin);
414	          continue;
415	        }
416	
417	      /* Skip LCD signal pins already in use */
418	
419	      if (pin == LCD_PIN_SCLK || pin == LCD_PIN_CS ||
420	          pin == LCD_PIN_MOSI || pin == LCD_PIN_DC  ||
421	          pin == LCD_PIN_RST   || pin == LCD_PIN_BL)
422	        {
423	          syslog(LOG_INFO,
424	                 "[scan] pin=%d skipped (LCD signal)\n", pin);
425	          continue;
426	        }
427	
428	      gpio_set_output(pin);
429	      gpio_write(pin, 1);
430	      up_mdelay(800);
431	
432	      syslog(LOG_INFO, "[scan] pin=%d high\n", pin);
433	    }
434	
435	  syslog(LOG_INFO,
436	         "[scan] done - check screen for any change\n");
437	
438	  return OK;
439	}
