441	/****************************************************************************
442	 * Name: lcdtest_pwr
443	 *
444	 * Description:
445	 *   Full power-on sequence with configurable GPIO range for binary-search
446	 *   identification of the LCD power enable pin.
447	 *
448	 *   Usage: lcdtest pwr [lo] [hi]
449	 *     lo..hi  — decimal GPIO range to drive high (default 0..52)
450	 *
451	 *   Always skips: 2,3,4,5,25,29 (LCD)  10,11 (UART)  7,8 (motor)
452	 *                 38,39 (LEDs)
453	 *
454	 ****************************************************************************/
455	
456	static int lcdtest_pwr(int lo, int hi)
457	{
458	  int pin;
459	  int count = 0;
460	  int off = 0;
461	  char pinbuf[256];
462	
463	  /* Step 1: drive GPIO lo..hi high, skip reserved pins.
464	   * Collect the actual pin list for the syslog dump.
465	   */
466	
467	  syslog(LOG_INFO,
468	         "[pwr] step1: GPIO %d-%d high (skip reserved)\n",
469	         lo, hi);
470	
471	  for (pin = lo; pin <= hi; pin++)
472	    {
473	      /* LCD signals */
474	
475	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
476	          pin == 25 || pin == 29)
477	        {
478	          continue;
479	        }
480	
481	      /* UART0 console */
482	
483	      if (pin == 10 || pin == 11)
484	        {
485	          continue;
486	        }
487	
488	      /* Vibration motor */
489	
490	      if (pin == 7 || pin == 8)
491	        {
492	          continue;
493	        }
494	
495	      /* Indicator LEDs */
496	
497	      if (pin == 38 || pin == 39)
498	        {
499	          continue;
500	        }
501	
502	      gpio_set_output(pin);
503	      gpio_write(pin, 1);
504	      count++;
505	
506	      if (off < (int)sizeof(pinbuf) - 8)
507	        {
508	          off += snprintf(pinbuf + off, sizeof(pinbuf) - off,
509	                          " %d", pin);
510	        }
511	    }
512	
513	  pinbuf[off] = '\0';
514	
515	  /* Print which pins were actually driven high */
516	
517	  syslog(LOG_INFO,
518	         "[pwr] driven high (%d pins):%s\n", count, pinbuf);
519	
520	  /* Step 2: wait for power rails to settle */
521	
522	  syslog(LOG_INFO, "[pwr] step2: wait 50 ms ...\n");
523	  up_mdelay(50);
524	
525	  /* Step 3: backlight on */
526	
527	  syslog(LOG_INFO, "[pwr] step3: backlight P25 high\n");
528	  gpio_set_output(LCD_PIN_BL);
529	  gpio_write(LCD_PIN_BL, 1);
530	
531	  /* Step 4: hardware reset */
532	
533	  syslog(LOG_INFO,
534	         "[pwr] step4: RST(P29) low 15 ms then high\n");
535	  gpio_set_output(LCD_PIN_RST);
536	  gpio_write(LCD_PIN_RST, 0);
537	  up_mdelay(15);
538	  gpio_write(LCD_PIN_RST, 1);
539	  up_mdelay(120);
540	
541	  /* Step 5: GC9D01 init sequence */
542	
543	  syslog(LOG_INFO, "[pwr] step5: GC9D01 init sequence\n");
544	  lcd_init_sequence();
545	
546	  /* Step 6: clear screen to black */
547	
548	  syslog(LOG_INFO, "[pwr] step6: fill screen black\n");
549	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
550	
551	  /* Step 7: draw 40x40 red square at (60,60) */
552	
553	  syslog(LOG_INFO,
554	         "[pwr] step7: fill 40x40 red at (60,60)\n");
555	  lcd_fill_rect(60, 60,
556	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
557	                0xf800);
558	
559	  syslog(LOG_INFO,
560	         "[pwr] done (%d pins driven) - "
561	         "screen should show red on black\n",
562	         count);
563	  return OK;
564	}
