589	    {
590	      int lo = 0;
591	      int hi = 52;
592	
593	      if (argc > 2)
594	        {
595	          lo = atoi(argv[2]);
596	        }
597	
598	      if (argc > 3)
599	        {
600	          hi = atoi(argv[3]);
601	        }
602	
603	      if (lo < 0)
604	        {
605	          lo = 0;
606	        }
607	
608	      if (hi > 52)
609	        {
610	          hi = 52;
611	        }
612	
613	      if (lo > hi)
614	        {
615	          syslog(LOG_ERR,
616	                 "[pwr] error: lo(%d) > hi(%d)\n", lo, hi);
617	          return -EINVAL;
618	        }
619	
620	      return lcdtest_pwr(lo, hi);
621	    }
622	
623	  return lcdtest_stages();
624	}
