/****************************************************************************
 * Name: lcdtest_go
 *
 * Description:
 *   One-step reliable LCD bring-up.  Drives all GPIO power/enable pins
 *   high, waits for supply stabilisation, then initialises the GC9D01
 *   and draws the test pattern.  This is the production-ready flow
 *   confirmed through binary-search pin identification.
 *
 ****************************************************************************/

static int lcdtest_go(void)
{
  int pin;
  int count = 0;

  /* Step 1: drive GPIO 0-52 high, skip reserved pins */

  syslog(LOG_INFO,
         "[go] step1: GPIO 0-52 high (skip reserved)\n");

  for (pin = 0; pin <= 52; pin++)
    {
      /* LCD signals */

      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
          pin == 25 || pin == 29)
        {
          continue;
        }

      /* UART0 console */

      if (pin == 10 || pin == 11)
        {
          continue;
        }

      /* Vibration motor */

      if (pin == 7 || pin == 8)
        {
          continue;
        }

      /* Indicator LEDs */

      if (pin == 38 || pin == 39)
        {
          continue;
        }

      /* SWD debug port: SWCLK=20, SWDIO=21 */

      if (pin == 20 || pin == 21)
        {
          continue;
        }

      gpio_set_output(pin);
      gpio_write(pin, 1);
      count++;
    }

  syslog(LOG_INFO, "[go] step1 done: %d pins driven high\n", count);

  /* Step 2: wait for power rails to settle */

  syslog(LOG_INFO, "[go] step2: wait 50 ms\n");
  up_mdelay(50);

  /* Step 3: backlight on */

  syslog(LOG_INFO, "[go] step3: backlight P25 high\n");
  gpio_set_output(LCD_PIN_BL);
  gpio_write(LCD_PIN_BL, 1);

  /* Step 4: hardware reset */

  syslog(LOG_INFO,
         "[go] step4: RST(P29) low 15 ms then high\n");
  gpio_set_output(LCD_PIN_RST);
  gpio_write(LCD_PIN_RST, 0);
  up_mdelay(15);
  gpio_write(LCD_PIN_RST, 1);
  up_mdelay(120);

  /* Step 5: GC9D01 init sequence */

  syslog(LOG_INFO, "[go] step5: GC9D01 init sequence\n");
  lcd_init_sequence();

  /* Step 6: clear screen to black */

  syslog(LOG_INFO, "[go] step6: fill screen black\n");
  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);

  /* Step 7: draw 40x40 red square at (60,60) */

  syslog(LOG_INFO,
         "[go] step7: fill 40x40 red at (60,60)\n");
  lcd_fill_rect(60, 60,
                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
                0xf800);

  syslog(LOG_INFO,
         "[go] done - screen should show red on black\n");
  return OK;
}

